#ifdef UA_ENABLE_METHODCALLS
static std::map<void*, std::function<void(const UA_UInt32&, std::vector<OPCUA::Variant>&)>> methodAsync_bindings;
static void
methodCalled(UA_Client *client, void *userdata, UA_UInt32 requestId,
	UA_CallResponse *response) {

	printf("%-50s%i\n", "Called method for request ", requestId);
	size_t outputSize;
	UA_Variant *output;
	UA_StatusCode retval = response->responseHeader.serviceResult;
	if (retval == UA_STATUSCODE_GOOD) {
		if (response->resultsSize >= 1)
			retval = response->results[0].statusCode;
		else
			retval = UA_STATUSCODE_BADUNEXPECTEDERROR;
	}
	if (retval != UA_STATUSCODE_GOOD) {
		UA_CallResponse_clear(response);
	}

	/* Move the output arguments */
	output = response->results[0].outputArguments;
	outputSize = response->results[0].outputArgumentsSize;
	std::vector<OPCUA::Variant> outputs;
	auto it = methodAsync_bindings.find(client);
	if (it != methodAsync_bindings.end()) {
		for (size_t i = 0; i < outputSize; ++i) {
			outputs.push_back(OPCUA::Variant(output[i]));
		}
		// call bound function
		it->second(requestId, outputs);
	}
	
	response->results[0].outputArguments = NULL;
	response->results[0].outputArgumentsSize = 0;

	if (retval == UA_STATUSCODE_GOOD) {
		printf("---Method call was successful, returned %lu values.\n",
			(unsigned long)outputSize);
		UA_Array_delete(output, outputSize, &UA_TYPES[UA_TYPES_VARIANT]);
	}
	else {
		printf("---Method call was unsuccessful, returned %x values.\n",
			retval);
	}
	UA_CallResponse_clear(response);
}
#endif  /* UA_ENABLE_METHODCALLS */

