#ifdef UA_ENABLE_EXPERIMENTAL_HISTORIZING
static void
printUpdateType(UA_HistoryUpdateType type) {
	switch (type) {
	case UA_HISTORYUPDATETYPE_INSERT:
		spdlog::get("uacpp_logger")->info("Insert\n");
		return;
	case UA_HISTORYUPDATETYPE_REPLACE:
		spdlog::get("uacpp_logger")->info("Replace\n");
		return;
	case UA_HISTORYUPDATETYPE_UPDATE:
		spdlog::get("uacpp_logger")->info("Update\n");
		return;
	case UA_HISTORYUPDATETYPE_DELETE:
		spdlog::get("uacpp_logger")->info("Delete\n");
		return;
	default:
		spdlog::get("uacpp_logger")->info("Unknown\n");
		return;
	}
}
#endif

#ifdef UA_ENABLE_HISTORIZING
static void
printTimestamp(char *name, UA_DateTime& date) {
	UA_DateTimeStruct dts = UA_DateTime_toStruct(date + UA_DateTime_localTimeUtcOffset());
	if (name)
		spdlog::get("uacpp_logger")->info("{}: {:#02d}-{:#02d}-{:#04d} {:#02d}:{:#02d}:{:#02d}.{:#03d}, ", name,
			dts.day, dts.month, dts.year, dts.hour, dts.min, dts.sec, dts.milliSec);
	else
		spdlog::get("uacpp_logger")->info("{:#02d}-{:#02d}-{:#04d} {:#02d}:{:#02d}:{:#02d}.{:#03d}, ",
			dts.day, dts.month, dts.year, dts.hour, dts.min, dts.sec, dts.milliSec);

	date = UA_DateTime_toUnixTime(UA_DateTime_fromStruct(dts));

}

static void
printDataValue(UA_DataValue *value) {
	/* Print status and timestamps */
	if (value->hasServerTimestamp)
		printTimestamp((char*)"ServerTime", value->serverTimestamp);

	if (value->hasSourceTimestamp)
		printTimestamp((char*)"SourceTime", value->sourceTimestamp);

	if (value->hasStatus)
		spdlog::get("uacpp_logger")->info("Status {:#08x}, ", value->status);

	if (value->value.type == &UA_TYPES[UA_TYPES_UINT32]) {
		UA_UInt32 hrValue = *(UA_UInt32 *)value->value.data;
		spdlog::get("uacpp_logger")->info("Uint32Value {:d}\n", hrValue);
	}

	if (value->value.type == &UA_TYPES[UA_TYPES_INT32]) {
		UA_UInt32 hrValue = *(UA_UInt32 *)value->value.data;
		spdlog::get("uacpp_logger")->info("Uint32Value {:d}\n", hrValue);
	}

	if (value->value.type == &UA_TYPES[UA_TYPES_DOUBLE]) {
		UA_Double hrValue = *(UA_Double *)value->value.data;
		spdlog::get("uacpp_logger")->info("DoubleValue {:f}\n", hrValue);
	}
}


static UA_Boolean
readRaw(const UA_HistoryData *data, std::vector<UA_DataValue>& datas) {
	spdlog::get("uacpp_logger")->info("readRaw Value count: {0}\n", (long unsigned)data->dataValuesSize);

	/* Iterate over all values */
	for (UA_UInt32 i = 0; i < data->dataValuesSize; ++i)
	{
		printDataValue(&data->dataValues[i]);
		datas.push_back(data->dataValues[i]);
	}

	/* We want more data! */
	return true;
}

#ifdef UA_ENABLE_EXPERIMENTAL_HISTORIZING
static UA_Boolean
readRawModified(const UA_HistoryModifiedData *data) {
	spdlog::get("uacpp_logger")->info("readRawModified Value count: %lu\n", (long unsigned)data->dataValuesSize);

	/* Iterate over all values */
	for (size_t i = 0; i < data->dataValuesSize; ++i) {
		printDataValue(&data->dataValues[i]);
	}
	spdlog::get("uacpp_logger")->info("Modificaton Value count: %lu\n", data->modificationInfosSize);
	for (size_t j = 0; j < data->modificationInfosSize; ++j) {
		if (data->modificationInfos[j].userName.data)
			spdlog::get("uacpp_logger")->info("Username: %s, ", data->modificationInfos[j].userName.data);

		printTimestamp((char*)"Modtime", data->modificationInfos[j].modificationTime);
		printUpdateType(data->modificationInfos[j].updateType);
	}

	/* We want more data! */
	return true;
}

static UA_Boolean
readEvents(const UA_HistoryEvent *data) {
	printf("readEvent Value count: %lu\n", (long unsigned)data->eventsSize);
	for (size_t i = 0; i < data->eventsSize; ++i) {
		printf("Processing event: %lu\n", (long unsigned)i);
		for (size_t j = 0; j < data->events[i].eventFieldsSize; ++j) {
			printf("Processing %lu: %s\n", (long unsigned)j, data->events[i].eventFields[j].type->typeName);
		}
	}
	return true;
}
#endif

// UA_Client *  -- void handleVariableReadHisCallback(const std::string& nodePath, const std::vector<UA_DataValue> datas, const bool moreData)
static std::map<void*, std::function<void(const std::string& nodePath, const std::vector<UA_DataValue> datas, const bool moreData)>> variableReadHis_bindings;
static UA_Boolean
readHisCallback(UA_Client *client, const UA_NodeId *nodeId,
	UA_Boolean moreDataAvailable,
	const UA_ExtensionObject *data, void *unused) {
	spdlog::get("uacpp_logger")->info("\nRead historical callback:\n");
	spdlog::get("uacpp_logger")->info("\tHas more data:\t{0}\n\n", moreDataAvailable);
	std::vector<UA_DataValue> datas;
	if (data->content.decoded.type == &UA_TYPES[UA_TYPES_HISTORYDATA]) {
		bool ret = readRaw((UA_HistoryData*)data->content.decoded.data, datas);
	}
#ifdef UA_ENABLE_EXPERIMENTAL_HISTORIZING
	if (data->content.decoded.type == &UA_TYPES[UA_TYPES_HISTORYMODIFIEDDATA]) {
		return readRawModified((UA_HistoryModifiedData*)data->content.decoded.data);
	}
	if (data->content.decoded.type == &UA_TYPES[UA_TYPES_HISTORYEVENT]) {
		return readEvents((UA_HistoryEvent*)data->content.decoded.data);
	}
#endif

	auto it = variableReadHis_bindings.find(client);
	if (it != variableReadHis_bindings.end()) {
		// call bound function
		GenericClient* gclient = (GenericClient*)unused;
		std::string nodePath = gclient->getNodePathByNodeId(OPCUA::NodeId(*nodeId));
		it->second(nodePath, datas, moreDataAvailable);
	}
	return true;
}

#endif // UA_ENABLE_HISTORIZING


