OPCUA::StatusCode GenericClient::initCacheRuntime(std::string kvpath/* = ""*/)
{
	std::string std_rootDir = "";
	if (kvpath == "")
	{
		// mindscadasvc 运行时使用
		INIReader reader("runtime.ini");
		if (reader.ParseError() < 0) {
			std::cout << "Can't load 'runtime.ini'\n";
			return OPCUA::StatusCode::UNDEFINED;
		}
		std_rootDir = reader.Get("General", "CurrentProjectPath", "");
		std_rootDir += "/KV";
	}
	else {
		// mindscada gd运行时使用
		std_rootDir = kvpath + "/KV";
	}
#ifdef _WIN32
	std::wstring_convert<std::codecvt_utf8<wchar_t>> conv;
	std::wstring rootDir = conv.from_bytes(std_rootDir);
	//std::cout << rootDir.c_str() << "\n";
	//rootDir = L"C:/prj/cpro现场项目/server/KV";
	MMKV::initializeMMKV(rootDir);
#elif defined(__linux__)
	std::string rootDir = std_rootDir;
	MMKV::initializeMMKV(rootDir);
#endif
	setMMKVLevel();
	
	spdlog::stopwatch sw;
	spdlog::info("start initCacheRuntime");

	std::string std_id = "__varid__";
	MMKV* m_mmkv_id = MMKV::mmkvWithID(std_id, MMKVMode::MMKV_MULTI_PROCESS);
	if (m_mmkv_id) {
		bool mmkvEnabled = m_mmkv_id->getBool("_enabled_");
		if (mmkvEnabled) {
			spdlog::get("uacpp_logger")->info("__varid__ start load _enabled_ = true");
			std::vector<std::string> vPathKeys = m_mmkv_id->allKeys();
			for (std::string k : vPathKeys)
			{
				if (kvpath != "")
				{
					// mindscada gd运行时忽略s__根目录及其子节点
					if (k.find("s__") == 0)
						continue;
				}
				std::string v;
				bool bret = m_mmkv_id->getString(k, v);
				if (bret) {
					int find_pos = v.find("|", 0);
					if (find_pos > 0) {
						std::string ns = v.substr(0, find_pos);
						std::string id = v.substr(find_pos + 1, v.length() - find_pos + 1);
						int ins = std::stoi(ns);
						int iid = std::stoi(id);
						entityRegistry[k] = NodeId(iid, ins);
						//printf("%s = %-9d | %-9d\n",
						//	k.data(),
						//	ins,
						//	iid	// node id
						//);
						if(spdlog::get("uacpp_logger")->should_log(spdlog::level::info))
							spdlog::get("uacpp_logger")->info("{0} | {1:-9d} | {2:-9d}",
								k,
								ins,
								iid	// node id
							);
					}
				}
			}
			spdlog::get("uacpp_logger")->info("__varid__ load end");
		}
	}

	std::string std_id_type = "__varidtype__";
	MMKV* m_mmkv_id_type = MMKV::mmkvWithID(std_id_type, MMKVMode::MMKV_MULTI_PROCESS);
	if (m_mmkv_id_type) {
		bool mmkvEnabled = m_mmkv_id_type->getBool("_enabled_");
		if (mmkvEnabled) {
			spdlog::get("uacpp_logger")->info("__varidtype__ start load _enabled_ = true");
			std::vector<std::string> vPathKeys = m_mmkv_id_type->allKeys();
			for (std::string k : vPathKeys)
			{
				bool bret = false;
				uint32_t tpid = m_mmkv_id_type->getUInt32(k, 0, &bret);
				if (bret) {
					int find_pos = k.find("|", 0);
					if (find_pos > 0) {
						std::string ns = k.substr(0, find_pos);
						std::string id = k.substr(find_pos + 1, k.length() - find_pos + 1);
						int ins = std::stoi(ns);
						int iid = std::stoi(id);
						nodeTypeRegistry[NodeId(iid, ins)] = const_cast<UA_DataType*>(&UA_TYPES[tpid]);
						//printf("%-9d | %-9d = %-9d\n",
						//	ins,
						//	iid,	// node id
						//	tpid
						//);
						if (spdlog::get("uacpp_logger")->should_log(spdlog::level::info))
							spdlog::get("uacpp_logger")->info("{0:-9d} | {1:-9d} | {2:>9}", ins,
								iid,	// node id
								tpid);
					}
				}
			}
			spdlog::get("uacpp_logger")->info("__varidtype__ load end");
		}
	}
	spdlog::info("end initCacheRuntime elapsed {:.3} seconds", sw);//unit second

	std::string std_value = "__var__";
	m_mmkv_value = MMKV::mmkvWithID(std_value, MMKVMode::MMKV_MULTI_PROCESS);
	if (m_mmkv_value)
		spdlog::get("uacpp_logger")->info("__var__ init succeed");

	return OPCUA::StatusCode::ALL_OK;
}

