#ifdef UA_ENABLE_HISTORIZING
//
// startTime - Unit: s
// endTime - Unit: s
OPCUA::StatusCode GenericClient::readHistoryData(const std::string &nodePath, const OPCUA::Variant &startTime, const OPCUA::Variant &endTime, bool returnBounds/* = false*/, const int numValuesPerNode/* = 10*/)
{
	if (m_status != 0)
		return OPCUA::StatusCode::DISCONNECTED;
	OPCUA::StatusCode result = OPCUA::StatusCode::ERROR_COMMUNICATION;
#ifdef HAS_OPCUA
	// lock client mutex
	std::unique_lock<std::recursive_mutex> lock(clientMutex);

	// check if the entity ID can be found
	NodeId entityId = browseNodePath(nodePath);
	entityRegistry[nodePath] = entityId;
	UA_NodeId nodeid = entityId;

	if (entityId == UA_NODEID_NULL) {
		return OPCUA::StatusCode::WRONG_ID;
	}
	variableReadHis_bindings[client] = std::bind(&GenericClient::handleVariableReadHisCallback, this, std::placeholders::_1, std::placeholders::_2, std::placeholders::_3);
	UA_Int64 st_i64 = startTime.getValueAs<UA_Int64>();
	UA_Int64 et_i64 = endTime.getValueAs<UA_Int64>();
	
	// unit 1/10 us
	UA_DateTime st = UA_DateTime_fromUnixTime(st_i64);// +UA_DateTime_localTimeUtcOffset();//startTime.getValueAs<UA_DateTime>();
	UA_DateTime et = UA_DateTime_fromUnixTime(et_i64);// +UA_DateTime_localTimeUtcOffset();//endTime.getValueAs<UA_DateTime>();
	printf("----starttime=%lld, endtime=%lld, currentTime=%lld ", st,et, UA_DateTime_now());
	UA_StatusCode retval = UA_Client_HistoryRead_raw(client, &nodeid, readHisCallback,
		/*UA_DateTime_now() -1*60*60* 10000000, UA_DateTime_now()*/
		st, et, UA_STRING_NULL, returnBounds, numValuesPerNode, UA_TIMESTAMPSTORETURN_BOTH, (void *)this);

	if (retval == UA_STATUSCODE_GOOD) {
		result = OPCUA::StatusCode::ALL_OK;
	}
	else {
		printf("Failed. %s\n", UA_StatusCode_name(retval));
		result = OPCUA::StatusCode::METHOD_BAD_CALL;
	}

#endif // HAS_OPCUA

	return result;
}
#endif // UA_ENABLE_HISTORIZING

